1	#!/usr/bin/env bun
2	/**
3	 * resolve_entry_agent.ts — Parse the "/agent-name" slash command from the
4	 * first visible line of a newly-opened issue's body, and emit
5	 * agent/number/type/notify as step outputs for atomaton-entry.wac.ts.
6	 *
7	 * Env: NUMBER, SENDER (issue number + the user who opened it), GITHUB_EVENT_PATH
8	 * Writes to $GITHUB_OUTPUT: agent, number, type, notify -- only if a valid
9	 * slash command was found on the first line; otherwise writes nothing, so a
10	 * downstream `if: steps.resolve.outputs.agent != ''` naturally stays false.
11	 */
12	import { readFileSync, appendFileSync } from "node:fs";
13	import { isAgentName } from "../../domain/work/agent-name.ts";
14	import { defineScript } from "./lib/script-ref.ts";
15	
16	export const ref = defineScript(import.meta.url);
17	
18	interface GithubIssueOpenedEvent {
19	  issue?: { body?: string };
20	}
21	
22	/**
23	 * The line the command must be on: the first one that shows up when the issue is
24	 * read.
25	 *
26	 * Blank lines and HTML comments are skipped because neither is visible on the
27	 * rendered issue, so requiring the command literally first would fail on a body
28	 * that looks exactly right. Atomaton writes such comments itself — the
29	 * `atomaton:notify` tag `create_sub_issue` prefixes a body with is one — and an issue
30	 * that carried one silently started nothing.
31	 *
32	 * Nothing else is skipped. A command below a paragraph of prose is not a command
33	 * at the top, and reading further would turn any mention of `/engineer` in a
34	 * discussion into a dispatch.
35	 */
36	function commandLine(body: string): string {
37	  for (const raw of body.split("\n")) {
38	    const line = raw.trim();
39	    if (!line) continue;
40	    if (line.startsWith("<!--") && line.endsWith("-->")) continue;
41	    return line;
42	  }
43	  return "";
44	}
45	
46	function main(): void {
47	  const eventPath = process.env.GITHUB_EVENT_PATH;
48	  const number = process.env.NUMBER ?? "";
49	  const sender = process.env.SENDER ?? "";
50	  const githubOutput = process.env.GITHUB_OUTPUT;
51	
52	  if (!eventPath) {
53	    console.error("resolve_entry_agent: GITHUB_EVENT_PATH is not set");
54	    return;
55	  }
56	
57	  const event = JSON.parse(readFileSync(eventPath, "utf8")) as GithubIssueOpenedEvent;
58	  const body = event.issue?.body ?? "";
59	
60	  if (!commandLine(body).startsWith("/")) return;
61	  const agent = commandLine(body).slice(1).trim();
62	  if (!agent) return;
63	
64	  // The name is spliced into shell text downstream (`AGENT="${{ inputs.agent }}"`
65	  // in atomaton-runner) and into an agent-definition path, so anything that is not
66	  // a bare name stops here. Emitting no output leaves the caller's
67	  // `if: steps.resolve.outputs.agent != ''` false, which is the same no-op as an
68	  // issue that opened with no slash command at all.
69	  //
70	  // A warning rather than silence because the two realistic causes are a typo
71	  // and the documented-elsewhere habit of writing instructions on the command
72	  // line: `/engineer implement X` reads as valid to a human and is not.
73	  if (!isAgentName(agent)) {
74	    console.error(
75	      `::warning::Ignoring '/${agent}': an agent command must be a bare name on its own line ` +
76	        `(for example '/engineer'), with any instructions on the lines after it.`,
77	    );
78	    return;
79	  }
80	
81	  if (githubOutput) {
82	    appendFileSync(githubOutput, [`agent=${agent}`, `number=${number}`, "type=issue", `notify=${sender}`].join("\n") + "\n");
83	  }
84	}
85	
86	if (import.meta.main) main();

